public object FfiConverterTypeEdgeTools: FfiConverter<EdgeTools, Long> {
    override fun lower(value: EdgeTools): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): EdgeTools {
        return EdgeTools(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): EdgeTools {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: EdgeTools) = 8UL

    override fun write(value: EdgeTools, buf: ByteBuffer) {
