    uniffiRustCallWithError(EternException) { _status ->
    UniffiLib.uniffi_etern_ffi_fn_constructor_outbox_new(
    
        
        FfiConverterString.lower(`path`),_status)
}
    )

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_etern_ffi_fn_free_outbox(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_etern_ffi_fn_clone_outbox(handle, status)
        }
    }

    
    /**
     * Appends one turn, flushed to the OS before returning.
     */
    @Throws(EternException::class)override fun `appendSyncTurn`(`turn`: SyncTurnDto)
        = 
    callWithHandle {
    uniffiRustCallWithError(EternException) { _status ->
    UniffiLib.uniffi_etern_ffi_fn_method_outbox_append_sync_turn(
        it,
        
        FfiConverterTypeSyncTurnDto.lower(`turn`),_status)
}
    }
    
    

    
    /**
     * Discard the outbox after a push has been acked.
     */
    @Throws(EternException::class)override fun `clear`()
        = 
    callWithHandle {
    uniffiRustCallWithError(EternException) { _status ->
    UniffiLib.uniffi_etern_ffi_fn_method_outbox_clear(
        it,
        _status)
}
    }
    
    

    
    @Throws(EternException::class)override fun `lenBytes`(): kotlin.Long {
            return FfiConverterLong.lift(
    callWithHandle {
    uniffiRustCallWithError(EternException) { _status ->
    UniffiLib.uniffi_etern_ffi_fn_method_outbox_len_bytes(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * Seq to use for the next append.
     */
    @Throws(EternException::class)override fun `nextSeq`(): kotlin.Long {
            return FfiConverterLong.lift(
    callWithHandle {
    uniffiRustCallWithError(EternException) { _status ->
    UniffiLib.uniffi_etern_ffi_fn_method_outbox_next_seq(
        it,
        _status)
}
    }
    )
    }
    

    
    @Throws(EternException::class)override fun `readAll`(): SyncTurnList {
            return FfiConverterTypeSyncTurnList.lift(
    callWithHandle {
    uniffiRustCallWithError(EternException) { _status ->
    UniffiLib.uniffi_etern_ffi_fn_method_outbox_read_all(
        it,
        _status)
}
    }
    )
    }
    

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}


/**
 * @suppress
 */
public object FfiConverterTypeOutbox: FfiConverter<Outbox, Long> {
    override fun lower(value: Outbox): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): Outbox {
        return Outbox(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): Outbox {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: Outbox) = 8UL

    override fun write(value: Outbox, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



