sealed class EternException: kotlin.Exception() {
    
    class Io(
        
        val v1: kotlin.String
        ) : EternException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Invalid(
        
        val v1: kotlin.String
        ) : EternException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Budget(
        
        val v1: kotlin.String
        ) : EternException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Other(
        
        val v1: kotlin.String
        ) : EternException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<EternException> {
        override fun lift(error_buf: RustBuffer.ByValue): EternException = FfiConverterTypeEternError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeEternError : FfiConverterRustBuffer<EternException> {
    override fun read(buf: ByteBuffer): EternException {
        

        return when(buf.getInt()) {
            1 -> EternException.Io(
                FfiConverterString.read(buf),
                )
            2 -> EternException.Invalid(
                FfiConverterString.read(buf),
                )
            3 -> EternException.Budget(
                FfiConverterString.read(buf),
                )
            4 -> EternException.Other(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: EternException): ULong {
        return when(value) {
            is EternException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is EternException.Invalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is EternException.Budget -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is EternException.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: EternException, buf: ByteBuffer) {
        when(value) {
            is EternException.Io -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is EternException.Invalid -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is EternException.Budget -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is EternException.Other -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
